package com.fitai.app.food

import com.fitai.app.model.FoodItem
import com.fitai.app.model.FoodServing
import fitai.core.data.generated.resources.Res
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.jetbrains.compose.resources.ExperimentalResourceApi

/**
 * The offline food database shipped with the app: `composeResources/files/foods.json`, generated by
 * `core/data/fooddb/build_foods.py` (sources in `core/data/fooddb/README.md`). Parsed once, then cached.
 */
class BundledFoodDataSource(
    private val load: suspend () -> String = ::readBundledJson,
) {
    private val mutex = Mutex()
    private var cache: List<FoodItem>? = null

    suspend fun foods(): List<FoodItem> = mutex.withLock {
        cache ?: parseFoodDatabase(load()).also { cache = it }
    }
}

@OptIn(ExperimentalResourceApi::class)
private suspend fun readBundledJson(): String = Res.readBytes(FOODS_PATH).decodeToString()

internal const val FOODS_PATH = "files/foods.json"

private val foodJson = Json { ignoreUnknownKeys = true }

/** Parses the bundled JSON; entries with a blank id or name or negative values are skipped. */
fun parseFoodDatabase(raw: String): List<FoodItem> =
    foodJson.decodeFromString(FoodDatabaseDto.serializer(), raw).foods
        .filter { it.id.isNotBlank() && (it.tr.isNotBlank() || it.en.isNotBlank()) && it.kcal >= 0 && it.p >= 0 && it.c >= 0 && it.f >= 0 }
        .map { dto ->
            FoodItem(
                id = dto.id,
                nameTr = dto.tr,
                nameEn = dto.en,
                category = dto.cat,
                kcalPer100g = dto.kcal,
                proteinPer100g = dto.p,
                carbsPer100g = dto.c,
                fatPer100g = dto.f,
                fiberPer100g = dto.fiber,
                servings = dto.s.filter { it.g > 0 }.map { FoodServing(it.u, it.g) },
                tags = dto.tags.toSet(),
                keywords = dto.kw,
                isCustom = false,
                source = dto.src,
            )
        }

@Serializable
internal data class FoodDatabaseDto(
    val version: Int = 1,
    val foods: List<FoodDto> = emptyList(),
)

/** Short keys keep the bundled file small: names, category, per-100 g values, servings, tags, keywords, source. */
@Serializable
internal data class FoodDto(
    val id: String = "",
    val tr: String = "",
    val en: String = "",
    val cat: String = "",
    val kcal: Double = 0.0,
    val p: Double = 0.0,
    val c: Double = 0.0,
    val f: Double = 0.0,
    val fiber: Double? = null,
    val s: List<ServingDto> = emptyList(),
    val tags: List<String> = emptyList(),
    val kw: List<String> = emptyList(),
    val src: String? = null,
)

@Serializable
internal data class ServingDto(val u: String = "", val g: Double = 0.0)
